import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Session validation
function validateSession(token) {
  if (!token) return null;
  try {
    const [payload, sig] = token.split('.');
    const expected = crypto.createHmac('sha256', process.env.SESSION_SECRET || 'dev-secret')
      .update(payload).digest('hex');
    if (sig === expected) {
      return JSON.parse(Buffer.from(payload, 'base64').toString());
    }
  } catch (e) { /* invalid token */ }
  return null;
}

// Product search endpoint with filtering
app.get('/api/products/search', async (req, res) => {
  const session = validateSession(req.headers['x-session-token']);
  const { q, category, sort_by, order, limit } = req.query;

  // Build base query
  let query = 'SELECT id, name, price, category, description FROM products WHERE 1=1';
  const params = [];
  let paramIdx = 1;

  if (q) {
    params.push(`%${q}%`);
    query += ` AND (name ILIKE $${paramIdx} OR description ILIKE $${paramIdx})`;
    paramIdx++;
  }

  if (category) {
    params.push(category);
    query += ` AND category = $${paramIdx}`;
    paramIdx++;
  }

  // Sort - validated against allowlist... partially
  const allowedSorts = ['name', 'price', 'created_at', 'category'];
  if (sort_by && allowedSorts.includes(sort_by.split(' ')[0])) {
    query += ` ORDER BY ${sort_by}`;
    if (order && ['asc', 'desc'].includes(order.toLowerCase())) {
      query += ` ${order}`;
    }
  } else {
    query += ' ORDER BY name ASC';
  }

  // Limit
  const parsedLimit = parseInt(limit) || 20;
  query += ` LIMIT ${Math.min(parsedLimit, 100)}`;

  try {
    const result = await pool.query(query, params);
    res.json({ products: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Admin: bulk price update
app.post('/api/admin/bulk-update', async (req, res) => {
  const session = validateSession(req.headers['x-session-token']);
  if (!session || session.role !== 'admin') {
    return res.status(403).json({ error: 'forbidden' });
  }

  const { updates } = req.body;
  if (!Array.isArray(updates)) return res.status(400).json({ error: 'invalid' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const u of updates) {
      await client.query(
        'UPDATE products SET price = $1 WHERE id = $2',
        [u.price, u.id]
      );
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'update failed' });
  } finally {
    client.release();
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000);
